      this.buildMode = true;
      this.player.group.visible = false;
      this.buildState = {
        lotId, category: 'furniture', item: 'bed', eraser: false,
        paint: this.state.home.layouts[lotId]?.baseColor || PAINTS[1], rot: 0, cell: null, valid: false,
