.mission-panel {
  position: absolute; top: 118px; left: 24px; width: 282px; padding: 14px 15px 12px;
  background: linear-gradient(115deg, rgba(12,15,11,.92), rgba(12,15,11,.58)); border-left: 2px solid var(--acid);
  backdrop-filter: blur(9px); clip-path: polygon(0 0, 100% 0, 100% calc(100% - 9px), calc(100% - 9px) 100%, 0 100%);
  box-shadow: 0 16px 45px rgba(0,0,0,.16);
}
.mission-head { display: flex; justify-content: space-between; align-items: center; font-family: var(--mono); font-size: 7.5px; letter-spacing: .16em; color: var(--acid); }
