.action-bar { position: absolute; bottom: max(22px, calc(16px + var(--safe-bottom))); left: 50%; transform: translateX(-50%); display: flex; align-items: stretch; padding: 4px; background: rgba(8,11,7,.85); border: 1px solid var(--line-soft); backdrop-filter: blur(12px); box-shadow: 0 18px 50px rgba(0,0,0,.24); }
.action-btn { position: relative; border: 0; background: transparent; min-width: 55px; padding: 6px 7px 4px; display: flex; flex-direction: column; align-items: center; gap: 2px; transition: background .18s, color .18s; }
