.action-btn:hover { background: rgba(216,255,69,.08); color: var(--acid); }
.action-btn span { font-family: var(--mono); font-size: 6.5px; letter-spacing: .08em; }
.action-btn kbd { position: absolute; top: 2px; right: 3px; border: 0; background: transparent; font-size: 5.5px; color: #586051; padding: 0; }
.action-btn em { position: absolute; top: 2px; right: 4px; font-family: var(--mono); font-size: 6px; font-style: normal; color: var(--acid); }
.ico { width: 18px; height: 18px; display: block; background: currentColor; opacity: .8; }
