.ico-people { clip-path: polygon(25% 0, 42% 0, 50% 23%, 58% 0, 75% 0, 82% 40%, 70% 45%, 70% 100%, 30% 100%, 30% 45%, 18% 40%); }
.ico-hammer { clip-path: polygon(0 72%, 55% 12%, 100% 55%, 46% 100%, 31% 72%, 16% 88%, 0 72%); }
.ico-bag { clip-path: polygon(18% 30%, 82% 30%, 94% 100%, 6% 100%); }
