@keyframes toastIn { from { opacity: 0; transform: translateY(-7px) } to { opacity: 1; transform: none } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-5px) } }

.context-menu { position: absolute; z-index: 12; pointer-events: none; display: none; }

.car-hud { position: absolute; right: 38px; bottom: 210px; width: 180px; text-align: right; }
