.car-speed b { font-size: 56px; font-weight: 800; letter-spacing: -.03em; text-shadow: 0 0 16px rgba(216,255,69,.15); }
.car-speed span { font-family: var(--mono); font-size: 8px; color: var(--muted); }
.car-gear { display: inline-grid; place-items: center; width: 24px; height: 24px; border: 1px solid var(--acid); color: var(--acid); font-family: var(--mono); font-size: 11px; margin-top: -4px; }
.car-name { font-family: var(--mono); font-size: 7px; letter-spacing: .14em; color: var(--acid); margin-top: 7px; }
.car-exit { font-family: var(--mono); font-size: 6.5px; color: var(--muted); margin-top: 8px; }
.aim-reticle { position: absolute; left: 50%; top: 50%; width: 24px; height: 24px; transform: translate(-50%,-50%); border: 1px solid rgba(216,255,69,.4); border-radius: 50%; }
.aim-reticle::after { content: ''; position: absolute; left: 50%; top: 50%; width: 3px; height: 3px; background: var(--acid); transform: translate(-50%,-50%); border-radius: 50%; }
.damage-flash { position: absolute; inset: 0; pointer-events: none; opacity: 0; background: radial-gradient(ellipse at center, transparent 35%, rgba(255,30,30,.5)); transition: opacity .2s; z-index: 8; }
.damage-flash.on { opacity: 1; transition: opacity .05s; }

.mobile-controls { display: none; }
