    ctx.fillStyle = cone; ctx.beginPath(); ctx.moveTo(0, 0); ctx.arc(0, 0, W * .48, -Math.PI / 2 - .45, -Math.PI / 2 + .45); ctx.closePath(); ctx.fill(); ctx.restore();
